// MAP.md: the system model in one page an agent reads first. One line per domain, system and component,
// where each lives in code, how current that is, and how to ask for more.
import type { MapFact, SystemMap } from '@/application/system-map';
import { type Component, homeLabel, type System } from '@/domain/workspace';

const ENTRY_TYPES = new Set(['endpoint', 'message', 'operation', 'interaction', 'handler']);

export function mapMarkdownOf(map: SystemMap): string {
  const { workspace } = map;
  const lines = [
    `# ${workspace.name}: system map`,
    '',
    'Generated by `npm run map -- md`. Do not edit; edit the YAML beside it and regenerate.',
    '',
    'Answer from the map first, then open the cited file at the cited lines. Ask it with',
    `\`npm run map -- <command> --workspace ${workspace.id}\`:`,
    '',
    '- `find <words>`: facts whose id, name or summary hold the words',
    '- `show <id>`: the fact, its code sources (permalinks), what it calls and what calls it, and when',
    '- `callers <id>`: who reaches it, up to three hops',
    '- `calls <id>`: the call tree under an endpoint, message or handler',
    '- `owns <path>`: the facts read from a file',
    '- `repos`: the commit each repo was last read at',
    '',
    ...reposSection(map),
    ...workspace.domains.flatMap((domain) => [
      `## ${domain.name} (\`${domain.id}\`)`,
      '',
      ...(domain.purpose === null ? [] : [domain.purpose, '']),
      ...domain.systems.flatMap((system) => systemSection(map, system, teamName(map, system))),
    ]),
  ];
  return `${lines.join('\n').trimEnd()}\n`;
}

function reposSection(map: SystemMap): string[] {
  if (map.repos.length === 0) return [];
  return [
    '## Repos',
    '',
    '| Repo | System | Read at | Since |',
    '| --- | --- | --- | --- |',
    ...map.repos.map(
      (repo) =>
        `| ${homeLabel(repo)} | ${repo.system} | ${readAt(repo.head, repo.scannedAt)} | ${movedAt(repo)} |`,
    ),
    '',
  ];
}

function teamName(map: SystemMap, system: System): string {
  return map.workspace.teams.find(({ id }) => id === system.team)?.name ?? system.team ?? 'unknown';
}

function readAt(head: string | null, at: string | null): string {
  if (head === null) return 'not scanned';
  const short = head.slice(0, 7);
  return at === null ? short : `${short} (${at})`;
}

function movedAt(repo: SystemMap['repos'][number]): string {
  const { head, checked } = repo;
  if (head === null || checked === null) return 'not checked';
  if (checked.tip === head) return `up to date (${checked.at})`;
  const by = checked.behind === null ? 'moved on' : `${String(checked.behind)} commits behind`;
  return `${by} at ${checked.tip.slice(0, 7)} (${checked.at})`;
}

function systemSection(map: SystemMap, system: System, team: string): string[] {
  const repos =
    system.repos.length === 0 ? 'no repo listed' : system.repos.map(homeLabel).join(', ');
  return [
    `### ${system.name} (\`${system.id}\`)`,
    '',
    `Team: ${team}. Code: ${repos}.`,
    '',
    ...system.components.map((component) => componentLine(map, component)),
    '',
  ];
}

function componentLine(map: SystemMap, component: Component): string {
  const entries = [...map.facts.values()].filter(
    (fact) =>
      fact.component === component.id && fact.id !== component.id && ENTRY_TYPES.has(fact.type),
  );
  const kind = component.tech === null ? component.type : `${component.type}, ${component.tech}`;
  const head = `- \`${component.id}\` ${component.name} (${kind})`;
  const does = component.does === null ? '' : `: ${component.does}`;
  const where = whereOf(map.facts.get(component.id));
  const offers = entries.length === 0 ? '' : `\n  - offers ${entries.map(codeOf).join(', ')}`;
  return `${head}${does}${where}${offers}`;
}

function codeOf(fact: MapFact): string {
  return `\`${fact.id}\``;
}

function whereOf(fact: MapFact | undefined): string {
  const source = fact?.sources[0];
  return source === undefined ? '' : `\n  - code: ${source.repo} \`${source.path}\``;
}
